"""Goal-led public contributor/provider map using the existing commons renderer."""
import hashlib,json,re
from html import escape as E
from urllib.parse import urlsplit

def validate(data):
 if set(data)!={'schema_version','mission','mission_source','scope','goals','entities','contributions','return_path'} or data['schema_version']!=1:raise ValueError('Unselected stewardship fields')
 if data['mission_source']!='PURPOSE.md':raise ValueError('Use the selected purpose source')
 if not 1<=len(data['goals'])<=10 or not 1<=len(data['entities'])<=100:raise ValueError('Unbounded selected map')
 def rows(values,fields):
  ids=set()
  for v in values:
   if set(v)!=set(fields) or not all(isinstance(v[k],str) for k in fields):raise ValueError('Unselected map fields or types')
   if not re.fullmatch('[a-z][a-z0-9-]*',v['id']) or v['id'] in ids:raise ValueError('Invalid map identity')
   ids.add(v['id'])
  return ids
 goals=rows(data['goals'],['id','title','question','offer','route']);entities=rows(data['entities'],['id','name','kind','suggested_role','source','status'])
 for g in data['goals']:
  if g['route'] not in {'corpus.html','help.html#organizing','method.html','network.html#resources'}:raise ValueError('Unknown goal route')
 for e in data['entities']:
  if e['kind'] not in {'provider','source','organization','role'}:raise ValueError('Unselected role')
  if e['source']:
   u=urlsplit(e['source'])
   if u.scheme!='https' or not u.hostname or u.username or u.password:raise ValueError('Unsafe map source')
 for c in data['contributions']:
  if set(c)!={'goal','entity','question','first_step','status'} or not all(isinstance(v,str) for v in c.values()) or c['goal'] not in goals or c['entity'] not in entities:raise ValueError('Unresolved contribution')
 return data

def render(data,version,providers=False):
 by={e['id']:e for e in data['entities']};title='Providers, by the purpose they could serve' if providers else 'Where can you help?'
 lead='A data source belongs beside the question it could help answer. These are public references, not a list of our accounts or purchases.' if providers else data['mission']
 h='<article class="stewardship"><h1>'+title+'</h1><p class="intro">'+E(lead)+'</p><p>Find your organization or kind of work. Our suggested role is a starting point for you to correct.</p><nav class="goal-index" aria-label="Project goals">'+''.join('<a href="#goal-'+g['id']+'">'+E(g['title'])+'</a>' for g in data['goals'])+'</nav>'
 h+='<form id="map-search" hidden><label for="find-place">Find yourself, an organization or a role</label><input id="find-place" type="search" placeholder="Name, source, skill or question" autocomplete="off"><p id="map-results" role="status" aria-live="polite"></p></form><p><a href="#respond" id="not-listed">I am not listed / I can help another way</a> · <a href="'+('stewardship.html' if providers else 'vendors.html')+'">'+('All contributor roles' if providers else 'Provider directory')+'</a></p>'
 for g in data['goals']:
  entries=''
  for c in data['contributions']:
   e=by[c['entity']]
   if c['goal']!=g['id'] or (providers and e['kind'] not in {'provider','source'}):continue
   source='<a href="'+E(e['source'],quote=True)+'" rel="noreferrer">Public source</a>' if e['source'] else 'An open role; no person is assigned.'
   entries+='<details class="map-role" id="role-'+g['id']+'-'+e['id']+'" data-goal="'+g['id']+'" data-entity="'+e['id']+'"><summary><strong>'+E(e['name'])+'</strong><span>'+E(e['suggested_role'])+'</span></summary><div class="role-detail"><p><strong>Shared question:</strong> '+E(c['question'])+'</p><p><strong>A useful first step:</strong> '+E(c['first_step'])+'</p><p><strong>What we can offer:</strong> '+E(g['offer'])+'</p><p class="scope-note">'+E(c['status'])+'. '+source+'</p><a class="map-respond" href="#respond" data-goal="'+g['id']+'" data-entity="'+e['id']+'">Correct this role or offer help</a></div></details>'
  if entries:h+='<section class="map-goal" id="goal-'+g['id']+'"><h2>'+E(g['title'])+'</h2><p>'+E(g['question'])+'</p><p><a href="'+g['route']+'">Related work and needs</a></p>'+entries+'</section>'
 h+='''<p id="map-empty" hidden>No listed role matches. You can propose another contribution below.</p><section id="respond" class="map-response"><h2>What should we change or work on together?</h2><p>Reply to the person who shared this page. This optional worksheet prepares a response with the goal and map version attached; it does not send anything.</p><noscript><p>Include the goal, role, your correction or offer, and what would help you. Responses stay private unless publication is agreed.</p></noscript><form id="map-response" hidden><label for="response-goal">Project goal</label><select id="response-goal">'''+''.join('<option value="'+g['id']+'">'+E(g['title'])+'</option>' for g in data['goals'])+'''</select><label for="response-entity">Where you fit</label><select id="response-entity"><option value="unlisted">Not listed / another role</option>'''+''.join('<option value="'+e['id']+'">'+E(e['name'])+'</option>' for e in data['entities'])+'''</select><label for="response-name">Your name or organization (optional)</label><input id="response-name" maxlength="160" autocomplete="organization"><label for="response-text">Your correction, question or contribution</label><textarea id="response-text" required maxlength="5000" placeholder="What can you help with, what have we missed, or what would make this useful to you?"></textarea><label for="response-permission">How may we use this response?</label><select id="response-permission"><option value="private">Keep it private to the review team</option><option value="ask">Ask before naming me or publishing</option></select><p class="scope-note">A data offer grants no access or license. A public edition needs separate rights review and exact release authorization. This worksheet verifies no identity or authority.</p><button type="submit">Prepare my response</button><section id="response-preview" hidden><label for="prepared-response">Copy this into your reply</label><textarea id="prepared-response" readonly></textarea><button type="button" id="copy-response">Copy response</button><button type="button" id="download-response">Download structured response</button><p id="response-status" role="status"></p></section></form></section><details class="map-context"><summary>How this map is maintained</summary><p>These are proposed contributions to goals, not memberships, purchases, endorsements or rankings. Providers can serve several goals; communities, reviewers, creators and maintainers can contribute without becoming vendors.</p><p>We aim to return a disposition and preserve disagreements. Hosted intake and update preferences are not connected here; use the existing invitation/reply channel.</p><p><a href="PURPOSE.md">Project purpose</a> · <a href="CONTRIBUTION-PROTOCOL.md">Contribution protocol</a> · <a href="help.html">Other needs</a> · <a href="stewardship.json">Read the map</a></p></details></article>'''
 payload=json.dumps({'version':version,'data':data},ensure_ascii=False).replace('<','\\u003c')
 return '<link rel="stylesheet" href="stewardship.css">'+h+'<script type="application/json" id="stewardship-data">'+payload+'</script><script src="stewardship.js" defer></script>'

def add_views(root,files,page):
 raw=(root/'data/stewardship.json').read_bytes();data=validate(json.loads(raw));version=hashlib.sha256(raw).hexdigest()
 files['stewardship.json']=raw
 for name in ['stewardship.js','stewardship.css']:files[name]=(root/name).read_bytes()
 files['stewardship.html']=page('Where can you help?',render(data,version));files['vendors.html']=page('Providers and project goals',render(data,version,True))
 return version
