(() => {
 const node = document.getElementById('stewardship-data'); if (!node) return;
 const {version, data} = JSON.parse(node.textContent);
 const el = id => document.getElementById(id);
 const goals = new Map(data.goals.map(g => [g.id,g]));
 const entities = new Map(data.entities.map(e => [e.id,e]));
 let prepared = null;
 el('map-search').hidden = false; el('map-response').hidden = false;
 const invalidate = () => { prepared = null; el('response-preview').hidden = true; el('response-status').textContent = ''; };
 el('map-response').addEventListener('input',invalidate);
 document.querySelectorAll('.map-respond').forEach(a => a.addEventListener('click',() => {
  el('response-goal').value = a.dataset.goal; el('response-entity').value = a.dataset.entity; invalidate();
 }));
 el('not-listed').addEventListener('click',() => {el('response-entity').value = 'unlisted'; invalidate();});
 el('find-place').addEventListener('input',() => {
  const terms = el('find-place').value.toLocaleLowerCase().trim().split(/\s+/).filter(Boolean); let count = 0;
  document.querySelectorAll('.map-role').forEach(r => {r.hidden = !terms.every(t => r.textContent.toLocaleLowerCase().includes(t)); if (!r.hidden) count++;});
  document.querySelectorAll('.map-goal').forEach(g => {g.hidden = !Array.from(g.querySelectorAll('.map-role')).some(r => !r.hidden);});
  el('map-results').textContent = count + ' suggested roles match. These are proposals, not verified memberships.';
  el('map-empty').hidden = count !== 0;
 });
 el('map-response').addEventListener('submit',event => {
  event.preventDefault(); const text = el('response-text').value.trim(); if (!text) {el('response-text').focus(); return;}
  const goal = el('response-goal').value, entity = el('response-entity').value;
  prepared = {schema_version:1,kind:'stewardship-contribution-draft',map_sha256:version,goal_id:goal,entity_id:entity === 'unlisted' ? null : entity,reported_name:el('response-name').value.trim() || null,contribution:text,usage:el('response-permission').value,status:'prepared; not submitted, verified, licensed or published'};
  el('prepared-response').value = 'Praxis · collective stewardship\nMap version: '+version+'\nGoal: '+goals.get(goal).title+' ('+goal+')\nRole: '+(entities.get(entity)?.name || 'Not yet listed')+'\nName/organization: '+(prepared.reported_name || 'Not supplied')+'\n\n'+text+'\n\nUsage: '+(prepared.usage === 'private' ? 'Private to review team' : 'Ask before naming or publishing')+'\nNo data license or identity verification is granted by this response.';
  el('response-preview').hidden = false; el('response-status').textContent = 'Prepared locally. Copy this into your reply; nothing has been sent.';
 });
 el('copy-response').addEventListener('click',async () => {
  if (!prepared) return;
  try {await navigator.clipboard.writeText(el('prepared-response').value); el('response-status').textContent = 'Copied. Paste into your reply; it has not been sent.';}
  catch {el('prepared-response').focus(); el('prepared-response').select(); el('response-status').textContent = 'Select and copy the text, then paste it into your reply.';}
 });
 el('download-response').addEventListener('click',() => {
  if (!prepared) return;
  const url=URL.createObjectURL(new Blob([JSON.stringify(prepared,null,2)+'\n'],{type:'application/json'}));
  const a=document.createElement('a'); a.href=url; a.download='praxis-contribution.json'; a.click(); setTimeout(() => URL.revokeObjectURL(url),1000);
  el('response-status').textContent='Draft downloaded. Return it through the invitation channel; nothing has been submitted.';
 });
})();
