(r/'handoff.py').write_text('''"""Selected collaborator handoff. Read-only observation every minute; loopback only."""
import argparse,datetime,hashlib,json,os,re,subprocess,sys,threading
from html import escape
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
from pathlib import Path
from urllib.request import Request,build_opener,HTTPRedirectHandler
from urllib.error import HTTPError
from install import validate
ROOT=Path(__file__).resolve().parent
READER='https://praxis-reader.ethical-capital.workers.dev/'

def sha(raw):return hashlib.sha256(raw).hexdigest()
def source_digest(root=ROOT):
 selected=[]
 for p in sorted(root.rglob('*')):
  rel=p.relative_to(root)
  if any(x.startswith('.') or x in {'public','__pycache__'} for x in rel.parts):continue
  if p.is_file() and p.suffix in {'.py','.js','.css','.html','.json','.csv','.md'}:selected.append([str(rel),sha(p.read_bytes())])
 return sha(json.dumps(selected,separators=(',',':')).encode())

class NoRedirect(HTTPRedirectHandler):
 def redirect_request(self,*args,**kwargs):return None

def reader_probe(expected):
 try:
  with build_opener(NoRedirect).open(Request(READER,headers={'User-Agent':'Praxis-selected-status/1'}),timeout=5) as response:
   body=response.read(65537)
   if response.status==200 and len(body)<=65536 and sha(body)==expected:return 'verified','Public reader responds with the pinned edition index.'
   return 'attention','Reader response differs from the pinned edition index.'
 except Exception:return 'unknown','Reader could not be verified in this check.'

def observe(observed_at,verification,root=ROOT,probe=reader_probe):
 # Explicit public projection: never serialize git status, environment, logs or DB rows.
 result={'schema_version':1,'observed_at':observed_at,'interval_seconds':60,'reader_url':READER,'checks':[]}
 try:
  manifest=validate(root/'public');manifest_sha=sha((root/'public/manifest.json').read_bytes());valid=True
 except Exception:manifest_sha=None;valid=False
 current=bool(valid and verification.get('passed') and verification.get('source_sha256')==source_digest(root) and verification.get('manifest_sha256')==manifest_sha)
 result['checks'].append({'id':'local','title':'Local research and contributor build','state':'verified' if current else 'attention','detail':'Manifest hashes and source-bound checks match this build.' if current else 'Local build needs a fresh source-bound check.','evidence':manifest_sha})
 result['checks'].append({'id':'tests','title':'Automated checks','state':'verified' if current else 'unknown','detail':str(verification.get('tests',0))+' tests passed at '+str(verification.get('verified_at','an unrecorded time'))+'.' if verification.get('passed') else 'No passing test receipt is available.','evidence':verification.get('source_sha256')})
 try:
  pin=json.loads((root.parent/'delivery/package-manifest.json').read_text());expected=pin['files']['index.html']['sha256'];state,detail=probe(expected)
 except Exception:state,detail='unknown','No usable pinned public-reader reference.'
 result['checks'].append({'id':'reader','title':'Public Anthropic paper reader','state':state,'detail':detail,'evidence':expected if 'expected' in locals() else None})
 result['checks'].append({'id':'pilot','title':'Pilot access and contribution flow','state':'local','detail':'Local contributor map and reply preparation exist. Access is arranged with the inviter; hosted enrollment and shared submission are not connected.','evidence':None})
 return result

def verify(output,root=ROOT):
 before=source_digest(root)
 run=subprocess.run([sys.executable,'-B','-m','unittest','discover','-s',str(root),'-p','test_*.py'],cwd=root.parent,capture_output=True,text=True,timeout=120)
 after=source_digest(root);match=re.search(r'Ran (\\d+) tests?',run.stderr)
 try:validate(root/'public');manifest=sha((root/'public/manifest.json').read_bytes())
 except Exception:manifest=None
 doc={'verified_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'passed':run.returncode==0 and before==after and manifest is not None,'tests':int(match[1]) if match else 0,'source_sha256':after,'manifest_sha256':manifest}
 atomic(output,json.dumps(doc,indent=2).encode());return doc

def atomic(path,raw):
 path.parent.mkdir(parents=True,exist_ok=True);temp=path.with_name(path.name+'.tmp');temp.write_bytes(raw);os.replace(temp,path)

def render(status,root=ROOT):
 css=(root.parent/'search/search.css').read_text()+'\\n'+(root/'handoff.css').read_text()
 template=(root/'templates/handoff.html').read_text()
 checks=''.join('<tr><th scope="row">'+escape(c['title'])+'</th><td><span class="state '+c['state']+'">'+escape(c['state'])+'</span></td><td>'+escape(c['detail'])+'</td></tr>' for c in status['checks'])
 payload=json.dumps(status,ensure_ascii=False).replace('<',chr(92)+'u003c')
 return template.replace('{{css}}',css).replace('{{checks}}',checks).replace('{{observed_at}}',escape(status['observed_at'])).replace('{{payload}}',payload).replace('{{script}}',(root/'handoff.js').read_text())

def refresh(output,verification,root=ROOT):
 try:receipt=json.loads(verification.read_text())
 except Exception:receipt={}
 now=datetime.datetime.now(datetime.timezone.utc).isoformat();status=observe(now,receipt,root)
 atomic(output/'status.json',(json.dumps(status,indent=2)+'\\n').encode());atomic(output/'index.html',render(status,root).encode());return status

def serve(output,verification,port):
 refresh(output,verification)
 stop=threading.Event()
 def ticker():
  while not stop.wait(60):
   try:refresh(output,verification)
   except Exception:pass # Last observation remains timestamped and visibly expires.
 class Handler(BaseHTTPRequestHandler):
  def log_message(self,*args):pass
  def do_GET(self):
   if self.headers.get('Host','') not in {'127.0.0.1:'+str(port),'localhost:'+str(port)}:self.send_error(403);return
   name={'/':'index.html','/index.html':'index.html','/status.json':'status.json','/download.html':'index.html'}.get(self.path)
   if name is None:self.send_error(404);return
   raw=(output/name).read_bytes();self.send_response(200);self.send_header('Content-Type','application/json' if name.endswith('.json') else 'text/html; charset=utf-8');self.send_header('Content-Length',str(len(raw)));self.send_header('Cache-Control','no-store');self.send_header('X-Content-Type-Options','nosniff')
   if self.path=='/download.html':self.send_header('Content-Disposition','attachment; filename="praxis-collaborator.html"')
   self.end_headers();self.wfile.write(raw)
 httpd=ThreadingHTTPServer(('127.0.0.1',port),Handler)
 threading.Thread(target=ticker,daemon=True).start()
 print('Praxis handoff running at http://127.0.0.1:'+str(port)+'/',flush=True)
 try:httpd.serve_forever()
 finally:stop.set();httpd.server_close()

if __name__=='__main__':
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output',type=Path,required=True);p.add_argument('--verify',action='store_true');p.add_argument('--serve',action='store_true');p.add_argument('--port',type=int,default=8857);a=p.parse_args();receipt=a.output/'verification.json'
 if a.verify:print(json.dumps(verify(receipt)))
 if a.serve:serve(a.output,receipt,a.port)
 else:print(json.dumps(refresh(a.output,receipt)))
''')
