// Compatibility of the public reader's exact route map. No routing side effects.
export function checkCompatibility(baseline, candidate) {
  const findings = [];
  for (const [path, previous] of Object.entries(baseline.routes)) {
    const current = Object.hasOwn(candidate, path) ? candidate[path] : null;
    if (!current) { findings.push(`${path}: removed route`); continue; }
    for (const field of ['key', 'type', 'download', 'archive']) {
      if (previous[field] !== current[field]) findings.push(`${path}: changed ${field}`);
    }
    if (path.startsWith('/papers/')) {
      for (const field of ['sha256', 'bytes']) {
        if (previous[field] !== current[field]) findings.push(`${path}: changed immutable ${field}`);
      }
    }
  }
  return findings;
}
