});
test('additive capability is permitted',()=>{
  assert.deepEqual(checkCompatibility(baseline,{...routes,'/new-capability/':{key:'new/index.html',type:'text/html'}}),[]);
});
test('removing an existing link is caught',()=>{
  const candidate={...routes};delete candidate['/archive.html'];
  assert(checkCompatibility(baseline,candidate).includes('/archive.html: removed route'));
});
test('changing an old route destination is caught',()=>{
  const candidate={...routes,'/archive.html':{...routes['/archive.html'],key:'new/index.html'}};
  assert(checkCompatibility(baseline,candidate).includes('/archive.html: changed key'));
});
test('silently replacing a published edition is caught',()=>{
  const path=Object.keys(routes).find(p=>p.startsWith('/papers/'));
  const candidate={...routes,[path]:{...routes[path],sha256:'0'.repeat(64)}};
  assert(checkCompatibility(baseline,candidate).includes(`${path}: changed immutable sha256`));
});
